import * as THREE from 'three';
import { ganzi, dayPillarIndex, STEM_ELEM } from './saju.js';

export const SKINS = ['#fde3cf', '#f6cfae', '#e9b88f', '#c98f62', '#9a6643', '#6b4430'];
export const HAIR_COLORS = ['#1b1a1f', '#3a2a22', '#6b4a32', '#b8863b', '#c9c9cf', '#d86a8a', '#5a78c8', '#7a4fb0'];
export const OUTFIT_COLORS = ['#f4efe4', '#2f3a5a', '#b23a48', '#3f7d5a', '#d9a441', '#7a5aa8', '#8aa7c9', '#2a2a2e'];
export const HAIR_STYLES = [['short', '짧은 머리'], ['bob', '단발'], ['long', '긴 생머리'], ['pony', '포니테일'], ['bun', '쪽머리'], ['curly', '곱슬 펌'], ['buzz', '스포츠 컷'], ['beanie', '비니']];
export const OUTFITS = [['hanbok', '한복'], ['hoodie', '후드티'], ['suit', '정장'], ['dress', '원피스'], ['cardigan', '가디건'], ['uniform', '교복'], ['hiking', '등산복'], ['knit', '니트']];
export const BUILDS = [['slim', '슬림'], ['normal', '보통'], ['sturdy', '듬직']];
export const HEIGHTS = [['short', '아담'], ['normal', '보통'], ['tall', '훤칠']];

export const DEFAULT_LOOK = { name: '', skin: 1, hair: 'short', hairColor: 0, outfit: 'hoodie', outfitColor: 7, build: 'normal', height: 'normal', glasses: false, scarf: false, ilju: null };

/* 오행 색 (일주 라벨은 일간 오행 기준: 목 초록 · 화 빨강 · 토 황토 · 금 은백 · 수 파랑) */
export const ELEM_COLORS = [['#3fa66a', '#fff'], ['#e4572e', '#fff'], ['#d9a441', '#2b1d05'], ['#cfd4dc', '#222'], ['#3a6ea5', '#fff']];

export function iljuFromBirth(y, m, d) { return ganzi(dayPillarIndex(y, m, d)); }
export function iljuLabelOf(g) { return { text: g.name + '일주', hanja: g.hanja, color: ELEM_COLORS[STEM_ELEM[g.stem]] }; }

const M = (c, o = {}) => new THREE.MeshStandardMaterial({ color: c, roughness: 0.85, metalness: 0, ...o });
const eyeMat = new THREE.MeshStandardMaterial({ color: '#25202a', roughness: 0.9 });
const blushMat = new THREE.MeshStandardMaterial({ color: '#f29aa0', roughness: 1, transparent: true, opacity: 0.55 });

function mesh(geo, mat, x = 0, y = 0, z = 0) { const m = new THREE.Mesh(geo, mat); m.position.set(x, y, z); m.castShadow = true; return m; }

export function buildAvatar(look) {
  const L = { ...DEFAULT_LOOK, ...look };
  const root = new THREE.Group();
  const body = new THREE.Group(); root.add(body);
  const skin = M(SKINS[L.skin]), hairM = M(HAIR_COLORS[L.hairColor], { roughness: 0.7 }), cloth = M(OUTFIT_COLORS[L.outfitColor]);
  const dark = M('#2a2a2e'), white = M('#f7f3ea');
  const wx = { slim: 0.88, normal: 1, sturdy: 1.15 }[L.build], hy = { short: 0.9, normal: 1, tall: 1.1 }[L.height];
  body.scale.set(1, hy, 1);
  const female = ['dress'].includes(L.outfit) || (L.outfit === 'hanbok' && ['long', 'pony', 'bun', 'bob'].includes(L.hair));

  // 다리 · 신발
  const legs = [], shoes = [];
  for (const s of [-1, 1]) {
    const pivot = new THREE.Group(); pivot.position.set(s * 0.13 * wx, 0.5, 0);
    const pants = (L.outfit === 'dress' || L.outfit === 'uniform' && female) ? skin : (L.outfit === 'suit' ? dark : L.outfit === 'hanbok' ? white : M(L.outfit === 'hiking' ? '#3b4a3a' : '#33384a'));
    pivot.add(mesh(new THREE.CapsuleGeometry(0.085 * wx, 0.32, 4, 10), pants, 0, -0.2, 0));
    const shoe = mesh(new THREE.BoxGeometry(0.16, 0.09, 0.26), L.outfit === 'hanbok' ? M('#f4efe4') : M('#f7f3ea'), 0, -0.46, 0.04); pivot.add(shoe); shoes.push(shoe);
    body.add(pivot); legs.push(pivot);
  }
  // 몸통
  const torsoH = 0.5;
  const torso = mesh(new THREE.CylinderGeometry(0.2 * wx, 0.25 * wx, torsoH, 14), cloth, 0, 0.78, 0); body.add(torso);
  // 옷 디테일
  if (L.outfit === 'hanbok') {
    const skirtOrPants = female ? mesh(new THREE.ConeGeometry(0.36 * wx, 0.5, 18, 1, true), M(OUTFIT_COLORS[(L.outfitColor + 2) % 8]), 0, 0.43, 0) : mesh(new THREE.CylinderGeometry(0.23, 0.3, 0.3, 12), white, 0, 0.5, 0);
    skirtOrPants.material.side = THREE.DoubleSide; body.add(skirtOrPants);
    const collar = mesh(new THREE.TorusGeometry(0.17, 0.03, 8, 16), white, 0, 1.03, 0.02); collar.rotation.x = Math.PI / 2; body.add(collar);
    const band = mesh(new THREE.BoxGeometry(0.4 * wx, 0.04, 0.02), M('#b23a48'), 0, 0.97, 0.21 * wx); body.add(band);
  } else if (L.outfit === 'hoodie') {
    const hood = mesh(new THREE.TorusGeometry(0.17, 0.06, 10, 18), cloth, 0, 1.02, -0.03); hood.rotation.x = Math.PI / 2.4; body.add(hood);
    const pocket = mesh(new THREE.BoxGeometry(0.26, 0.1, 0.03), M('#00000022'), 0, 0.62, 0.23 * wx); pocket.material.transparent = true; pocket.material.opacity = 0.25; body.add(pocket);
  } else if (L.outfit === 'suit') {
    body.add(mesh(new THREE.BoxGeometry(0.08, 0.34, 0.02), white, 0, 0.9, 0.235 * wx));
    body.add(mesh(new THREE.BoxGeometry(0.035, 0.28, 0.02), M('#b23a48'), 0, 0.88, 0.25 * wx));
    for (const s of [-1, 1]) { const lap = mesh(new THREE.BoxGeometry(0.07, 0.3, 0.02), dark, s * 0.07, 0.9, 0.245 * wx); lap.rotation.z = s * 0.25; body.add(lap); }
  } else if (L.outfit === 'dress') {
    const sk = mesh(new THREE.ConeGeometry(0.34 * wx, 0.5, 18), cloth, 0, 0.5, 0); body.add(sk);
  } else if (L.outfit === 'cardigan') {
    body.add(mesh(new THREE.BoxGeometry(0.2, 0.46, 0.02), white, 0, 0.78, 0.24 * wx));
    for (const s of [-1, 1]) body.add(mesh(new THREE.BoxGeometry(0.02, 0.46, 0.04), M('#00000030'), s * 0.1, 0.78, 0.245 * wx));
  } else if (L.outfit === 'uniform') {
    const col = mesh(new THREE.TorusGeometry(0.17, 0.035, 8, 16), white, 0, 1.03, 0.0); col.rotation.x = Math.PI / 2; body.add(col);
    body.add(mesh(new THREE.BoxGeometry(0.12, 0.1, 0.02), M('#b23a48'), 0, 0.93, 0.245 * wx));
    if (female) body.add(mesh(new THREE.ConeGeometry(0.31 * wx, 0.3, 16), M('#2f3a5a'), 0, 0.56, 0));
  } else if (L.outfit === 'hiking') {
    body.add(mesh(new THREE.BoxGeometry(0.4 * wx, 0.07, 0.02), M('#f2c14e'), 0, 0.98, 0.215 * wx));
    body.add(mesh(new THREE.CylinderGeometry(0.13, 0.13, 0.04, 12), M('#f2c14e'), 0, 0.62, 0.23 * wx).rotateX(Math.PI / 2));
    body.add(mesh(new THREE.BoxGeometry(0.34 * wx, 0.4, 0.14), M('#6d5a3a'), 0, 0.82, -0.27)); // 배낭
  } else if (L.outfit === 'knit') {
    for (let i = 0; i < 3; i++) body.add(mesh(new THREE.TorusGeometry(0.22 * wx + i * 0.005, 0.012, 6, 20), M('#00000020'), 0, 0.62 + i * 0.12, 0).rotateX(Math.PI / 2));
    const turtle = mesh(new THREE.CylinderGeometry(0.1, 0.12, 0.1, 12), cloth, 0, 1.04, 0); body.add(turtle);
  }
  if (L.scarf) { const sc = mesh(new THREE.TorusGeometry(0.15, 0.055, 8, 16), M('#b23a48'), 0, 1.02, 0.01); sc.rotation.x = Math.PI / 2; body.add(sc); body.add(mesh(new THREE.BoxGeometry(0.07, 0.22, 0.03), M('#b23a48'), 0.07, 0.9, 0.2)); }

  // 팔
  const arms = [];
  for (const s of [-1, 1]) {
    const pivot = new THREE.Group(); pivot.position.set(s * 0.27 * wx, 0.98, 0);
    const sleeve = L.outfit === 'hanbok' ? M(OUTFIT_COLORS[L.outfitColor]) : cloth;
    pivot.add(mesh(new THREE.CapsuleGeometry(0.06 * wx, 0.26, 4, 10), sleeve, 0, -0.17, 0));
    pivot.add(mesh(new THREE.SphereGeometry(0.06, 10, 8), skin, 0, -0.38, 0));
    body.add(pivot); arms.push(pivot);
  }
  // 머리
  const head = new THREE.Group(); head.position.y = 1.2; body.add(head);
  const skull = mesh(new THREE.SphereGeometry(0.3, 24, 20), skin); skull.scale.set(1, 0.95, 0.96); head.add(skull);
  const eyes = [];
  for (const s of [-1, 1]) {
    const eye = mesh(new THREE.SphereGeometry(0.036, 10, 8), eyeMat, s * 0.105, 0.0, 0.27); eye.scale.set(1, 1.3, 0.5); head.add(eye); eyes.push(eye);
    const b = new THREE.Mesh(new THREE.CircleGeometry(0.05, 12), blushMat); b.position.set(s * 0.17, -0.07, 0.262); b.lookAt(s * 0.17, -0.07, 1); head.add(b);
  }
  const mouth = new THREE.Mesh(new THREE.TorusGeometry(0.035, 0.008, 6, 12, Math.PI), M('#9a4a4a')); mouth.position.set(0, -0.09, 0.285); mouth.rotation.z = Math.PI; head.add(mouth);
  head.add(mesh(new THREE.SphereGeometry(0.04, 8, 6), skin, 0, -0.03, 0.29)); // 코
  for (const s of [-1, 1]) head.add(mesh(new THREE.SphereGeometry(0.05, 8, 6), skin, s * 0.3, -0.02, 0)); // 귀
  if (L.glasses) for (const s of [-1, 1]) { const g = new THREE.Mesh(new THREE.TorusGeometry(0.065, 0.009, 6, 18), dark); g.position.set(s * 0.105, 0, 0.285); head.add(g); }
  // 머리카락
  const H = (geo, x, y, z, sx = 1, sy = 1, sz = 1) => { const m = mesh(geo, hairM, x, y, z); m.scale.set(sx, sy, sz); head.add(m); return m; };
  const cap = () => { const c = new THREE.Mesh(new THREE.SphereGeometry(0.325, 24, 16, 0, Math.PI * 2, 0, Math.PI * 0.56), hairM); c.position.set(0, 0.02, -0.01); c.rotation.x = -0.18; c.castShadow = true; head.add(c); };
  switch (L.hair) {
    case 'short': cap(); H(new THREE.BoxGeometry(0.4, 0.07, 0.06), 0, 0.17, 0.28); break;
    case 'bob': cap(); H(new THREE.CylinderGeometry(0.34, 0.34, 0.32, 24, 1, true, 0.95, Math.PI * 2 - 1.9), 0, -0.07, -0.02).material = new THREE.MeshStandardMaterial({ color: HAIR_COLORS[L.hairColor], side: THREE.DoubleSide, roughness: 0.7 }); break;
    case 'long': cap(); { const m = H(new THREE.CylinderGeometry(0.33, 0.28, 0.7, 24, 1, true, 0.95, Math.PI * 2 - 1.9), 0, -0.3, -0.03); m.material = new THREE.MeshStandardMaterial({ color: HAIR_COLORS[L.hairColor], side: THREE.DoubleSide, roughness: 0.7 }); } break;
    case 'pony': cap(); H(new THREE.SphereGeometry(0.1, 12, 10), 0, 0.08, -0.34); H(new THREE.CapsuleGeometry(0.07, 0.35, 4, 10), 0, -0.15, -0.38); break;
    case 'bun': cap(); H(new THREE.SphereGeometry(0.14, 14, 12), 0, 0.2, -0.28); break;
    case 'curly': for (let i = 0; i < 16; i++) { const a = i / 16 * Math.PI * 2, r = 0.27; H(new THREE.SphereGeometry(0.11, 8, 8), Math.cos(a) * r, 0.1 + (i % 2) * 0.1, Math.sin(a) * r - 0.04); } H(new THREE.SphereGeometry(0.28, 14, 10), 0, 0.2, -0.04); break;
    case 'buzz': { const c = new THREE.Mesh(new THREE.SphereGeometry(0.31, 20, 14, 0, Math.PI * 2, 0, Math.PI * 0.5), hairM); c.position.y = 0.02; head.add(c); } break;
    case 'beanie': { const c = new THREE.Mesh(new THREE.SphereGeometry(0.34, 20, 14, 0, Math.PI * 2, 0, Math.PI * 0.55), M(OUTFIT_COLORS[(L.outfitColor + 3) % 8])); c.position.set(0, 0.03, -0.01); c.castShadow = true; head.add(c); head.add(mesh(new THREE.SphereGeometry(0.06, 8, 8), white, 0, 0.35, 0)); H(new THREE.BoxGeometry(0.5, 0.1, 0.12), 0, 0.1, 0.22, 0.8, 1, 1).visible = false; } break;
    case 'bald': break;
  }
  // 신발 숨김 (실내 입장 시)
  root.userData = { legs, arms, head, body, shoes, wx, sitY: 0, eyes };
  root.userData.setShoes = v => shoes.forEach(s => s.visible = v);
  return root;
}

/* 걷기/앉기/가만히 애니메이션 */
export function animateAvatar(av, t, moving, sitting, praying = false) {
  const u = av.userData; const sw = moving ? Math.sin(t * 9) * 0.7 : 0;
  if (sitting) {
    u.legs[0].rotation.x = u.legs[1].rotation.x = -Math.PI / 2 + 0.1; u.body.position.y = -0.38;
    u.arms[0].rotation.x = u.arms[1].rotation.x = -0.6;
  } else {
    u.body.position.y = moving ? Math.abs(Math.sin(t * 9)) * 0.03 : Math.sin(t * 1.6) * 0.008;
    u.legs[0].rotation.x = sw; u.legs[1].rotation.x = -sw;
    u.arms[0].rotation.x = -sw * 0.8; u.arms[1].rotation.x = sw * 0.8;
    u.legs[0].rotation.z = 0; u.legs[1].rotation.z = 0;
  }
  if (praying) { u.arms[0].rotation.x = u.arms[1].rotation.x = -1.2; u.arms[0].rotation.z = -0.35; u.arms[1].rotation.z = 0.35; u.head.rotation.x = 0.25; }
  else { u.arms[0].rotation.z = 0.05; u.arms[1].rotation.z = -0.05; u.head.rotation.x = 0; }
}

/* 닉네임 + 일주 컬러 라벨 스프라이트 (MBTI 처럼 닉네임 위에 뜬다) */
export function makeNameTag(name, ilju, live = false) {
  const c = document.createElement('canvas'); c.width = 512; c.height = 160; const g = c.getContext('2d');
  const font = "'system-ui','Gowun Batang',sans-serif";
  let y = 100;
  if (ilju) {
    const lab = ilju.text; g.font = `700 36px ${font}`; const w = g.measureText(lab).width + 44;
    g.fillStyle = ilju.color[0]; g.beginPath(); g.roundRect(256 - w / 2, 14, w, 52, 26); g.fill();
    g.strokeStyle = 'rgba(255,255,255,.85)'; g.lineWidth = 3; g.stroke();
    g.fillStyle = ilju.color[1]; g.textAlign = 'center'; g.textBaseline = 'middle'; g.fillText(lab, 256, 41);
  } else y = 70;
  g.font = `600 40px ${font}`; g.textAlign = 'center'; g.textBaseline = 'middle'; g.lineWidth = 8; g.strokeStyle = 'rgba(20,16,30,.85)'; g.strokeText(name, 256, y + 10); g.fillStyle = '#fff'; g.fillText(name, 256, y + 10); if (live) { const tw = g.measureText(name).width; g.fillStyle = '#3ddc84'; g.strokeStyle = 'rgba(20,16,30,.9)'; g.lineWidth = 4; g.beginPath(); g.arc(256 - tw / 2 - 22, y + 8, 9, 0, 7); g.stroke(); g.fill(); }
  const tex = new THREE.CanvasTexture(c); tex.colorSpace = THREE.SRGBColorSpace;
  const sp = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthTest: false })); sp.scale.set(1.9, 0.6, 1); sp.renderOrder = 10; sp.position.y = 1.95;
  return sp;
}

/* 운명론자 선생님: 사진 속 모델을 캐릭터화 (쪽머리 · 베이지 린넨 가디건 · 올리브 셔츠 · 잔잔한 미소) */
export const TEACHER_LOOK = { name: '운명론자 선생님', skin: 0, hair: 'bun', hairColor: 0, outfit: 'cardigan', outfitColor: 0, build: 'normal', height: 'normal', glasses: false };
export function buildTeacher() {
  const av = buildAvatar(TEACHER_LOOK);
  // 올리브 셔츠 칼라
  const col = new THREE.Mesh(new THREE.TorusGeometry(0.17, 0.04, 8, 16), new THREE.MeshStandardMaterial({ color: '#7d7f55', roughness: 0.9 })); col.position.set(0, 1.02, 0.02); col.rotation.x = Math.PI / 2; av.userData.body.add(col);
  const inner = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.46, 0.02), new THREE.MeshStandardMaterial({ color: '#7d7f55', roughness: 0.9 })); inner.position.set(0, 0.78, 0.245); av.userData.body.add(inner);
  // 은빛 몇 가닥
  const silver = new THREE.Mesh(new THREE.BoxGeometry(0.03, 0.2, 0.02), new THREE.MeshStandardMaterial({ color: '#c9c9cf' })); silver.position.set(-0.18, 0.1, 0.27); silver.rotation.z = 0.4; av.userData.head.add(silver);
  return av;
}

