/* 내 만세력 이미지 — 입력한 생년월일시로 사주팔자를 계산해 PNG로 그려 준다.
 * 모든 계산과 그리기는 브라우저 안에서만 일어나고, 입력값은 서버로 보내지 않는다. */
import { computeSaju, ganzi, STEMS, STEMS_H, BRANCHES, BRANCHES_H, ANIMALS, ELEM, ELEM_H, STEM_ELEM, BRANCH_ELEM, STEM_YANG, jieTimes, jdn } from './saju.js';

const JJ = [[8, 9], [9, 7, 5], [4, 2, 0], [0, 1], [1, 9, 4], [4, 6, 2], [2, 5, 3], [3, 1, 5], [4, 8, 6], [6, 7], [7, 3, 4], [4, 0, 8]];
const SSG = ['비견', '겁재', '식신', '상관', '편재', '정재', '편관', '정관', '편인', '정인'];
export const EL_COLOR = ['#3fa66a', '#e4572e', '#d9a441', '#9aa3b2', '#3a6ea5']; // 목화토금수
const EL_BG = ['#e5f4ea', '#fde8e1', '#faf0d6', '#eef0f4', '#e1ecf7'];

export function sipsung(dayStem, t) {
  const de = STEM_ELEM[dayStem], te = STEM_ELEM[t]; const same = STEM_YANG[dayStem] === STEM_YANG[t];
  const rel = ((te - de) % 5 + 5) % 5; // 0 같음, 1 내가 생함, 2 내가 극함, 3 나를 극함, 4 나를 생함
  const base = [0, 2, 4, 6, 8][rel];
  return SSG[base + (same ? 0 : 1)];
}

/* 음력 → 양력 (Intl 중국력 이용, 1900~2100) */
const fmtL = new Intl.DateTimeFormat('en-u-ca-chinese-nu-latn', { timeZone: 'Asia/Seoul', year: 'numeric', month: 'numeric', day: 'numeric' });
function lunarParts(date) { const o = {}; for (const p of fmtL.formatToParts(date)) o[p.type] = p.value; return { y: +o.relatedYear, m: parseInt(o.month, 10), leap: /bis/.test(o.month), d: +o.day }; }
export function lunarToSolar(y, m, d, leap) {
  const start = Date.UTC(y, 0, 10, 3), end = Date.UTC(y + 1, 2, 10, 3);
  for (let t = start; t <= end; t += 86400000) { const l = lunarParts(new Date(t)); if (l.y === y && l.m === m && l.d === d && l.leap === !!leap) { const dt = new Date(t); return { y: dt.getUTCFullYear(), m: dt.getUTCMonth() + 1, d: dt.getUTCDate() }; } }
  return null;
}

const SJ_HOUR = { 자시: [0, 0], 축시: [2, 0], 인시: [4, 0], 묘시: [6, 0], 진시: [8, 0], 사시: [10, 0], 오시: [12, 0], 미시: [14, 0], 신시: [16, 0], 유시: [18, 0], 술시: [20, 0], 해시: [22, 0] };

/* v: {name, y,m,d, cal, gender, tmode, hh, mi, sijin} → 결과 */
export function buildManse(v) {
  let { y, m, d } = { y: +v.y, m: +v.m, d: +v.d };
  let lunarNote = '';
  if (v.cal === 'lunar' || v.cal === 'leap_lunar') {
    const s = lunarToSolar(y, m, d, v.cal === 'leap_lunar');
    if (!s) return { error: '입력하신 음력 날짜를 찾지 못했어요. 날짜와 윤달 여부를 다시 확인해 주세요' };
    lunarNote = `음력 ${y}.${m}.${d}${v.cal === 'leap_lunar' ? ' (윤달)' : ''}`; y = s.y; m = s.m; d = s.d;
  }
  let h = null, mi = 0, timeLabel = '오시(시간 모름)'; let assumed = false;
  if (v.tmode === 'unknown' || (v.tmode === 'time' && (v.hh === '' || v.hh == null)) || (v.tmode === 'sijin' && !v.sijin)) { h = 12; mi = 0; assumed = true; }
  else if (v.tmode === 'time' && v.hh !== '' && v.hh != null) { h = +v.hh; mi = +(v.mi || 0); timeLabel = `${String(h).padStart(2, '0')}:${String(mi).padStart(2, '0')}`; }
  else if (v.tmode === 'sijin' && v.sijin) { [h, mi] = SJ_HOUR[v.sijin] || [null, 0]; timeLabel = v.sijin; }
  // 경도 보정 -30분을 적용하고, 보정 후 23시 이후는 다음 날 일주로 본다(사주랩과 동일 기준)
  let cy = y, cm = m, cd = d, ch = h, cmi = mi, dayShift = 0;
  if (h != null) { const dt = new Date(Date.UTC(y, m - 1, d, h, mi) - 30 * 60000); cy = dt.getUTCFullYear(); cm = dt.getUTCMonth() + 1; cd = dt.getUTCDate(); ch = dt.getUTCHours(); cmi = dt.getUTCMinutes(); if (ch >= 23) dayShift = 1; }
  const sj = computeSaju({ y: cy, m: cm, d: cd, h: ch, mi: cmi });
  let dayP = sj.pillars.day; if (dayShift) dayP = ganzi((dayP.idx + 1) % 60);
  let hourP = null;
  if (h != null) { const hb = Math.floor(((ch + 1) % 24) / 2); const hs = ((dayP.stem % 5) * 2 + hb) % 10; hourP = ganzi([...Array(60).keys()].find(n => n % 10 === hs && n % 12 === hb)); }
  const P = { year: sj.pillars.year, month: sj.pillars.month, day: dayP, hour: hourP };
  const ds = P.day.stem;
  const keys = ['hour', 'day', 'month', 'year']; // 사주표는 시·일·월·년 순(오른쪽이 연주)
  const cols = keys.map(k => {
    const p = P[k]; if (!p) return { key: k, empty: true };
    const jj = JJ[p.branch]; const main = jj[jj.length - 1];
    return { key: k, p, stemSS: k === 'day' ? '일간(나)' : sipsung(ds, p.stem), branchSS: sipsung(ds, main), hidden: jj.map(s => ({ s, name: STEMS[s], el: STEM_ELEM[s] })) };
  });
  // 오행 분포: 천간 + 지지 정기 (시 모르면 6글자)
  const cnt = [0, 0, 0, 0, 0]; let tot = 0;
  for (const c of cols) { if (c.empty) continue; cnt[STEM_ELEM[c.p.stem]]++; cnt[BRANCH_ELEM[c.p.branch]]++; tot += 2; }
  // 대운
  const male = v.gender === 'male'; const forward = (STEM_YANG[P.year.stem] === 1) === male;
  const jdB = jdn(cy, cm, cd) - 0.5 + ((h == null ? 12 : ch) + (h == null ? 0 : cmi) / 60) / 24 - 9 / 24;
  const list = [...jieTimes(y - 1), ...jieTimes(y), ...jieTimes(y + 1)].sort((a, b) => a - b);
  let prev = list[0], next = list[list.length - 1]; for (const t of list) { if (t <= jdB) prev = t; else { next = t; break; } }
  const days = forward ? next - jdB : jdB - prev; const startAge = Math.max(1, Math.round(days / 3));
  const mIdx = P.month.idx; const dae = [];
  for (let i = 1; i <= 8; i++) { const gi = ganzi((((mIdx + (forward ? i : -i)) % 60) + 60) % 60); dae.push({ age: startAge + (i - 1) * 10, g: gi, ss: sipsung(ds, gi.stem) }); }
  return { name: (v.name || '').trim(), y, m, d, timeLabel, assumed, lunarNote, male, forward, startAge, P, cols, cnt, tot, dae, animal: ANIMALS[P.year.branch], ilganElem: STEM_ELEM[ds], hasHour: !!hourP, nearJie: sj.near || sj.nearNoTime };
}

/* ---------- 그리기 ---------- */
function rr(c, x, y, w, h, r) { c.beginPath(); c.moveTo(x + r, y); c.arcTo(x + w, y, x + w, y + h, r); c.arcTo(x + w, y + h, x, y + h, r); c.arcTo(x, y + h, x, y, r); c.arcTo(x, y, x + w, y, r); c.closePath(); }
export async function renderManseImage(r) {
  try { await Promise.all(['800 40px "Nanum Myeongjo"', '700 30px "Gowun Batang"', '700 28px Pretendard'].map(f => document.fonts.load(f, '甲子사주'))); } catch { }
  const W = 1080, H = 1860, cv = document.createElement('canvas'); cv.width = W; cv.height = H; const c = cv.getContext('2d');
  const SERIF = '"Nanum Myeongjo","Noto Serif KR",serif', SANS = 'Pretendard,"Apple SD Gothic Neo",sans-serif';
  c.fillStyle = '#f7f0e1'; c.fillRect(0, 0, W, H);
  c.strokeStyle = '#c9a24a'; c.lineWidth = 6; rr(c, 22, 22, W - 44, H - 44, 28); c.stroke(); c.lineWidth = 2; rr(c, 36, 36, W - 72, H - 72, 22); c.stroke();
  c.textAlign = 'center'; c.fillStyle = '#8a5a1f'; c.font = `700 26px ${SANS}`; c.fillText('사람냄새 나는 온라인 사주상담소', W / 2, 92);
  c.fillStyle = '#1b1722'; c.font = `800 62px ${SERIF}`; c.fillText('運命論者', W / 2, 160);
  c.font = `800 40px ${SERIF}`; c.fillText(`${r.name || '손님'}님의 사주팔자`, W / 2, 222);
  c.font = `600 25px ${SANS}`; c.fillStyle = '#5b4a38';
  const g = r.male ? '남성' : '여성'; c.fillText(`${r.lunarNote ? r.lunarNote + ' → ' : ''}양력 ${r.y}년 ${r.m}월 ${r.d}일 ${r.timeLabel} · ${g} · ${r.animal}띠`, W / 2, 268);
  // 사주표
  const colW = 224, gap = 14, x0 = (W - (colW * 4 + gap * 3)) / 2; let y0 = 312;
  const heads = ['시주', '일주', '월주', '년주'];
  r.cols.forEach((col, i) => {
    const x = x0 + i * (colW + gap);
    c.fillStyle = '#1b1722'; rr(c, x, y0, colW, 46, 12); c.fill(); c.fillStyle = '#f4dd9a'; c.font = `700 24px ${SANS}`; c.fillText(heads[i], x + colW / 2, y0 + 31);
    if (col.empty) { c.fillStyle = '#e8e0cf'; rr(c, x, y0 + 56, colW, 640, 14); c.fill(); c.fillStyle = '#8a7a66'; c.font = `700 30px ${SANS}`; c.fillText('시간 모름', x + colW / 2, y0 + 380); return; }
    const se = STEM_ELEM[col.p.stem], be = BRANCH_ELEM[col.p.branch];
    c.fillStyle = '#6b5a45'; c.font = `700 22px ${SANS}`; c.fillText(col.stemSS, x + colW / 2, y0 + 86);
    c.fillStyle = EL_BG[se]; rr(c, x, y0 + 100, colW, 190, 16); c.fill(); c.strokeStyle = EL_COLOR[se]; c.lineWidth = 3; rr(c, x, y0 + 100, colW, 190, 16); c.stroke();
    c.fillStyle = EL_COLOR[se]; c.font = `800 118px ${SERIF}`; c.fillText(STEMS_H[col.p.stem], x + colW / 2, y0 + 220);
    c.font = `700 22px ${SANS}`; c.fillText(`${STEMS[col.p.stem]}${ELEM[se]}`, x + colW / 2, y0 + 270);
    c.fillStyle = EL_BG[be]; rr(c, x, y0 + 304, colW, 190, 16); c.fill(); c.strokeStyle = EL_COLOR[be]; c.lineWidth = 3; rr(c, x, y0 + 304, colW, 190, 16); c.stroke();
    c.fillStyle = EL_COLOR[be]; c.font = `800 118px ${SERIF}`; c.fillText(BRANCHES_H[col.p.branch], x + colW / 2, y0 + 424);
    c.font = `700 22px ${SANS}`; c.fillText(`${BRANCHES[col.p.branch]}${ELEM[be]}`, x + colW / 2, y0 + 474);
    c.fillStyle = '#6b5a45'; c.font = `700 22px ${SANS}`; c.fillText(col.branchSS, x + colW / 2, y0 + 526);
    c.fillStyle = '#fff'; rr(c, x, y0 + 546, colW, 150, 14); c.fill(); c.fillStyle = '#8a7a66'; c.font = `600 18px ${SANS}`; c.fillText('지장간', x + colW / 2, y0 + 572);
    const n = col.hidden.length; const bw = 62, bg = 8; const sx = x + colW / 2 - (n * bw + (n - 1) * bg) / 2;
    col.hidden.forEach((hd, k) => { const bx = sx + k * (bw + bg); c.fillStyle = EL_BG[hd.el]; rr(c, bx, y0 + 586, bw, 90, 10); c.fill(); c.fillStyle = EL_COLOR[hd.el]; c.font = `800 34px ${SERIF}`; c.fillText(STEMS_H[hd.s], bx + bw / 2, y0 + 626); c.font = `600 17px ${SANS}`; c.fillText(sipsung(r.P.day.stem, hd.s), bx + bw / 2, y0 + 660); });
  });
  // 오행 분포
  let y1 = y0 + 726; c.textAlign = 'left'; c.fillStyle = '#1b1722'; c.font = `800 30px ${SERIF}`; c.fillText('오행 분포', 70, y1);
  const maxc = Math.max(...r.cnt, 1); const barX = 70, barW = W - 140;
  r.cnt.forEach((n, i) => { const yy = y1 + 24 + i * 50; c.fillStyle = EL_COLOR[i]; c.font = `800 26px ${SERIF}`; c.fillText(`${ELEM_H[i]} ${ELEM[i]}`, barX, yy + 30);
    c.fillStyle = '#e6dcc6'; rr(c, barX + 120, yy + 8, barW - 220, 28, 14); c.fill(); if (n) { c.fillStyle = EL_COLOR[i]; rr(c, barX + 120, yy + 8, Math.max(28, (barW - 220) * n / Math.max(maxc, r.tot / 2.5)), 28, 14); c.fill(); }
    c.fillStyle = '#1b1722'; c.font = `700 24px ${SANS}`; c.textAlign = 'right'; c.fillText(`${n}`, barX + barW, yy + 31); c.textAlign = 'left'; });
  const lack = r.cnt.map((n, i) => [n, i]).filter(x => x[0] === 0).map(x => ELEM[x[1]]);
  c.fillStyle = '#5b4a38'; c.font = `600 23px ${SANS}`; c.textAlign = 'center';
  c.fillText(lack.length ? `이 사주에서 보이지 않는 오행: ${lack.join(', ')}  (재미로 보는 참고예요)` : '다섯 오행이 고루 들어 있어요', W / 2, y1 + 300);
  // 대운
  let y2 = y1 + 346; c.textAlign = 'left'; c.fillStyle = '#1b1722'; c.font = `800 30px ${SERIF}`; c.fillText(`대운 · ${r.startAge}세부터 10년 단위 (${r.forward ? '순행' : '역행'})`, 70, y2);
  const dw = 108, dg = 10, dx0 = (W - (dw * 8 + dg * 7)) / 2;
  r.dae.forEach((d, i) => { const x = dx0 + i * (dw + dg), se = STEM_ELEM[d.g.stem], be = BRANCH_ELEM[d.g.branch];
    c.textAlign = 'center'; c.fillStyle = '#fff'; rr(c, x, y2 + 20, dw, 196, 14); c.fill();
    c.fillStyle = '#6b5a45'; c.font = `700 22px ${SANS}`; c.fillText(`${d.age}세`, x + dw / 2, y2 + 50);
    c.fillStyle = EL_COLOR[se]; c.font = `800 52px ${SERIF}`; c.fillText(STEMS_H[d.g.stem], x + dw / 2, y2 + 108);
    c.fillStyle = EL_COLOR[be]; c.fillText(BRANCHES_H[d.g.branch], x + dw / 2, y2 + 166);
    c.fillStyle = '#8a7a66'; c.font = `600 17px ${SANS}`; c.fillText(d.ss, x + dw / 2, y2 + 202); });
  // 안내
  c.fillStyle = '#8a7a66'; c.font = `600 21px ${SANS}`; c.textAlign = 'center';
  const notes = [r.assumed ? "태어난 시각을 모르시면 '오시'로 봅니다." : '', '절기(입춘·절입 시각) 기준으로 계산했고, 경도 -30분 보정, 자시는 23:30~01:29로 봤어요.', r.nearJie ? '※ 태어난 시각이 절기 경계에 가까워 월주가 달라질 수 있어요.' : '', '전통 명리를 바탕으로 한 참고용 자료이며 중요한 결정을 대신하지 않아요.'].filter(Boolean);
  notes.forEach((t, i) => c.fillText(t, W / 2, H - 100 - notes.length * 30 + i * 30));
  c.fillStyle = '#8a5a1f'; c.font = `800 26px ${SERIF}`; c.fillText('運命論者 사주상담소', W / 2, H - 56);
  return cv;
}

js/manse-form.js:
/* 만세력 입력폼 (토스 무료 체험판)
 * 성별 / 양력·음력·음력 윤달 / 생년월일 / 태어난 시간(시간·시진·몰라요)
 * 제출하면 입력값만 onSubmit 으로 넘기고, 외부 사이트로 이동하거나 값을 서버로 보내지 않는다. */
export const MANSE_BASE = '';
export const SIJIN = [
  ['자시', '23:30~01:29'], ['축시', '01:30~03:29'], ['인시', '03:30~05:29'], ['묘시', '05:30~07:29'],
  ['진시', '07:30~09:29'], ['사시', '09:30~11:29'], ['오시', '11:30~13:29'], ['미시', '13:30~15:29'],
  ['신시', '15:30~17:29'], ['유시', '17:30~19:29'], ['술시', '19:30~21:29'], ['해시', '21:30~23:29'],
];

export function buildManseUrl() { return ''; } // 외부 이동 없음 (호환용)

export function validate(v) {
  const y = +v.y, m = +v.m, d = +v.d;
  if (!(y >= 1900 && y <= 2100)) return '태어난 해를 1900~2100 사이로 적어 주세요';
  if (!(m >= 1 && m <= 12)) return '월은 1~12 사이로 적어 주세요';
  if (!(d >= 1 && d <= 31)) return '일은 1~31 사이로 적어 주세요';
  if (v.tmode === 'time') {
    if (v.hh === '' || +v.hh < 0 || +v.hh > 23) return '시는 0~23 사이로 적어 주세요 (저녁 8시 30분이면 20 : 30)';
    if (v.mi !== '' && (+v.mi < 0 || +v.mi > 59)) return '분은 0~59 사이로 적어 주세요';
  }
  if (v.tmode === 'sijin' && !v.sijin) return '시진을 골라 주세요';
  return '';
}

/* root 안에 폼을 그린다. onSubmit(url, values) 호출. */
export function mountManseForm(root, { onSubmit, theme = 'light', prefill = {} } = {}) {
  const st = { gender: 'female', cal: 'solar', tmode: 'time', sijin: '', ...prefill };
  root.innerHTML = `
  <form class="mf ${theme}" novalidate>
    <div class="mf-row">
      <div class="mf-col"><label>성별</label><div class="mf-seg" data-k="gender">
        <button type="button" data-v="female">여성</button><button type="button" data-v="male">남성</button></div></div>
      <div class="mf-col"><label>달력</label><div class="mf-seg" data-k="cal">
        <button type="button" data-v="solar">양력</button><button type="button" data-v="lunar">음력</button><button type="button" data-v="leap_lunar">음력 윤달</button></div></div>
    </div>
    <div class="mf-row mf-date">
      <div class="mf-col"><label for="mf-y">태어난 해</label><input id="mf-y" name="y" inputmode="numeric" maxlength="4" placeholder="1990" autocomplete="off"></div>
      <div class="mf-col"><label for="mf-m">월</label><input id="mf-m" name="m" inputmode="numeric" maxlength="2" placeholder="7" autocomplete="off"></div>
      <div class="mf-col"><label for="mf-d">일</label><input id="mf-d" name="d" inputmode="numeric" maxlength="2" placeholder="15" autocomplete="off"></div>
    </div>
    <div class="mf-col"><label>태어난 시간</label><div class="mf-seg mf-seg-s" data-k="tmode">
      <button type="button" data-v="time">시간</button><button type="button" data-v="sijin">시진</button><button type="button" data-v="unknown">몰라요</button></div></div>
    <div class="mf-time" data-show="time"><div class="mf-row"><div class="mf-col"><input name="hh" inputmode="numeric" maxlength="2" placeholder="20" aria-label="시 (0부터 23)"></div>
      <span class="mf-colon">:</span><div class="mf-col"><input name="mi" inputmode="numeric" maxlength="2" placeholder="30" aria-label="분"></div></div>
      <p class="mf-hint">24시간으로 적어 주세요. 저녁 8시 30분이면 20 : 30 입니다.</p></div>
    <div class="mf-sijin" data-show="sijin"><p class="mf-hint">아래에서 시진을 고르세요</p><div class="mf-grid">
      ${SIJIN.map(([n, r]) => `<button type="button" data-sj="${n}"><b>${n}</b><small>${r}</small></button>`).join('')}</div></div>
    <p class="mf-hint" data-show="unknown"><b>태어난 시각을 모르시면 '오시'(11:30~13:29)로 봅니다.</b> 시주는 참고로만 봐 주세요.</p>
    <p class="mf-err" role="alert"></p>
    <div class="mf-foot"><button class="mf-go" type="submit">만세력 이미지 만들기 <i>→</i></button>
      <span class="mf-note">전화번호 없이 바로 확인. 입력한 생년월일은 저장하지 않아요.</span></div>
  </form>`;
  const form = root.querySelector('form');
  const sync = () => {
    form.querySelectorAll('.mf-seg').forEach(seg => seg.querySelectorAll('button').forEach(b => b.classList.toggle('on', st[seg.dataset.k] === b.dataset.v)));
    form.querySelectorAll('[data-show]').forEach(el => el.style.display = el.dataset.show === st.tmode ? '' : 'none');
    form.querySelectorAll('[data-sj]').forEach(b => b.classList.toggle('on', st.sijin === b.dataset.sj));
  };
  form.addEventListener('click', e => {
    const b = e.target.closest('button'); if (!b) return;
    const seg = b.closest('.mf-seg'); if (seg) { st[seg.dataset.k] = b.dataset.v; sync(); }
    if (b.dataset.sj) { st.sijin = b.dataset.sj; sync(); }
  });
  form.addEventListener('submit', e => {
    e.preventDefault();
    const fd = new FormData(form);
    const v = { gender: st.gender, cal: st.cal, tmode: st.tmode, sijin: st.sijin, y: fd.get('y').trim(), m: fd.get('m').trim(), d: fd.get('d').trim(), hh: (fd.get('hh') || '').trim(), mi: (fd.get('mi') || '').trim() };
    const err = validate(v); form.querySelector('.mf-err').textContent = err;
    if (err) return;
    onSubmit && onSubmit(buildManseUrl(v), v);
  });
  sync();
  return { form, state: st };
}

