import * as THREE from 'three';

const texLoader = new THREE.TextureLoader();
export function tex(name, rx = 1, ry = 1) {
  const t = texLoader.load(`assets/tex/${name}_diff.jpg`); t.wrapS = t.wrapT = THREE.RepeatWrapping; t.repeat.set(rx, ry); t.colorSpace = THREE.SRGBColorSpace; t.anisotropy = 4; return t;
}
const std = (o) => new THREE.MeshStandardMaterial({ roughness: 0.9, metalness: 0, ...o });
function box(w, h, d, mat, x, y, z, cast = true) { const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat); m.position.set(x, y, z); m.castShadow = cast; m.receiveShadow = true; return m; }
function cyl(rt, rb, h, mat, x, y, z, seg = 16) { const m = new THREE.Mesh(new THREE.CylinderGeometry(rt, rb, h, seg), mat); m.position.set(x, y, z); m.castShadow = true; m.receiveShadow = true; return m; }

export function canvasTex(w, h, draw) { const c = document.createElement('canvas'); c.width = w; c.height = h; draw(c.getContext('2d'), w, h); const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace; t.anisotropy = 4; return t; }
function signPlane(w, h, texture, emissive = 0.0) { return new THREE.Mesh(new THREE.PlaneGeometry(w, h), new THREE.MeshStandardMaterial({ map: texture, roughness: 0.8, emissive: new THREE.Color('#ffd9a0'), emissiveMap: texture, emissiveIntensity: emissive })); }

/* ===== 골목 (밤) ===== */
export function buildOutside() {
  const g = new THREE.Group();
  const ground = new THREE.Mesh(new THREE.PlaneGeometry(60, 40), std({ map: tex('gravelly_sand', 14, 9), color: '#8c8f9c' })); ground.rotation.x = -Math.PI / 2; ground.position.set(0, 0, 8); ground.receiveShadow = true; g.add(ground);
  // 돌길
  const path = new THREE.Mesh(new THREE.PlaneGeometry(4, 22), std({ map: tex('japanese_stone_wall', 2, 9), color: '#b9b4ad' })); path.rotation.x = -Math.PI / 2; path.position.set(0, 0.01, 6); path.receiveShadow = true; g.add(path);

  // 한옥 상담소 본채
  const wall = std({ map: tex('beige_wall_001', 5, 1.4), color: '#f2e3c6' });
  const wood = std({ map: tex('weathered_planks', 1, 1), color: '#6a3f26' });
  const roofM = std({ map: tex('grey_roof_tiles', 8, 2), color: '#555a66' });
  g.add(box(16, 3.2, 1.2, wall, 0, 1.6, -3));
  for (const x of [-7.6, -3.2, 3.2, 7.6]) g.add(box(0.35, 3.4, 0.5, wood, x, 1.7, -2.3));
  g.add(box(16.4, 0.3, 1.5, wood, 0, 3.3, -2.5));
  // 지붕
  const roof = new THREE.Mesh(new THREE.BoxGeometry(18, 0.35, 4.2), roofM); roof.position.set(0, 4.1, -3.2); roof.rotation.x = -0.32; roof.castShadow = true; g.add(roof);
  const roof2 = new THREE.Mesh(new THREE.BoxGeometry(18, 0.35, 3.6), roofM); roof2.position.set(0, 4.3, -5.4); roof2.rotation.x = 0.35; g.add(roof2);
  for (const s of [-1, 1]) { const e = new THREE.Mesh(new THREE.BoxGeometry(0.4, 0.5, 4.4), roofM); e.position.set(s * 9, 4.3, -3.4); g.add(e); }
  // 한지 창 (불빛)
  const paper = new THREE.MeshStandardMaterial({ color: '#ffe9b8', emissive: '#ffb347', emissiveIntensity: 0.9, roughness: 1 });
  for (const x of [-5.4, 5.4]) { g.add(box(3, 1.9, 0.12, paper, x, 1.7, -2.35, false)); for (let i = -1; i <= 1; i++) g.add(box(0.06, 1.9, 0.14, wood, x + i * 1, 1.7, -2.3, false)); g.add(box(3, 0.06, 0.14, wood, x, 1.7, -2.3, false)); }
  // 문 (두 짝)
  const doorFrame = box(3.6, 2.7, 0.35, wood, 0, 1.35, -2.35); g.add(doorFrame);
  for (const s of [-1, 1]) { g.add(box(1.55, 2.4, 0.1, paper, s * 0.85, 1.3, -2.15, false)); for (let i = 0; i < 4; i++) g.add(box(0.05, 2.4, 0.12, wood, s * 0.85 + (i - 1.5) * 0.38, 1.3, -2.1, false)); for (let j = 0; j < 5; j++) g.add(box(1.55, 0.05, 0.12, wood, s * 0.85, 0.3 + j * 0.5, -2.1, false)); }
  // 간판
  const signTex = canvasTex(1024, 256, (c, w, h) => {
    c.fillStyle = '#2a1a12'; c.fillRect(0, 0, w, h); c.strokeStyle = '#e6bd67'; c.lineWidth = 8; c.strokeRect(12, 12, w - 24, h - 24);
    c.fillStyle = '#f4dd9a'; c.textAlign = 'center'; c.textBaseline = 'middle'; c.font = "800 118px 'Nanum Myeongjo',serif"; c.fillText('運命論者', w / 2, 100);
    c.font = "700 54px 'Nanum Myeongjo',serif"; c.fillStyle = '#e8c978'; c.fillText('사 주 상 담 소', w / 2, 192);
  });
  const sign = signPlane(4.8, 1.2, signTex, 0.35); sign.position.set(0, 3.9, -1.65); g.add(sign);
  for (const s of [-1, 1]) g.add(box(0.1, 0.7, 0.1, wood, s * 2.2, 3.5, -1.7));
  // 세로 깃발
  const flagTex = canvasTex(256, 768, (c, w, h) => { c.fillStyle = '#b83a3a'; c.fillRect(0, 0, w, h); c.fillStyle = '#fbf3e4'; c.fillRect(14, 14, w - 28, h - 28); c.fillStyle = '#b83a3a'; c.font = "800 78px 'Nanum Myeongjo',serif"; c.textAlign = 'center'; ['四', '柱', '命', '理'].forEach((t, i) => c.fillText(t, w / 2, 150 + i * 150)); });
  for (const x of [-4.2, 4.2]) { const f = signPlane(0.9, 2.7, flagTex, 0.15); f.position.set(x, 1.8, -1.55); g.add(f); g.add(cyl(0.04, 0.04, 1, wood, x, 3.5, -1.55)); }
  // 홍등
  const lights = [];
  for (const x of [-6.5, -2.9, 2.9, 6.5]) {
    const l = new THREE.Mesh(new THREE.SphereGeometry(0.28, 14, 12), new THREE.MeshStandardMaterial({ color: '#d8392b', emissive: '#ff4a2b', emissiveIntensity: 1.3 })); l.scale.y = 1.2; l.position.set(x, 2.9, -1.3); g.add(l);
    g.add(box(0.02, 0.4, 0.02, wood, x, 3.25, -1.3, false)); g.add(cyl(0.12, 0.12, 0.05, wood, x, 3.12, -1.3)); g.add(cyl(0.1, 0.1, 0.05, wood, x, 2.65, -1.3));
  }
  for (const x of [-4.5, 4.5]) { const p = new THREE.PointLight('#ff8a4a', 14, 9, 1.8); p.position.set(x, 2.8, -0.6); g.add(p); }
  // 신발장 (현관 앞)
  g.add(box(2.4, 0.5, 0.7, wood, 5.6, 0.25, -1.3));
  // 이웃 가게 (장식)
  const shop = (x, w, name, color) => {
    g.add(box(w, 3.4, 3, std({ color: '#cbbfa8', map: tex('beige_wall_001', 2, 1) }), x, 1.7, -3.6));
    const t = canvasTex(512, 128, (c, ww, hh) => { c.fillStyle = color; c.fillRect(0, 0, ww, hh); c.fillStyle = '#fff'; c.font = "800 62px 'Nanum Myeongjo',serif"; c.textAlign = 'center'; c.textBaseline = 'middle'; c.fillText(name, ww / 2, 70); });
    const s = signPlane(w * 0.7, 0.8, t, 0.5); s.position.set(x, 2.8, -2.05); g.add(s);
    g.add(box(w * 0.75, 1.5, 0.1, new THREE.MeshStandardMaterial({ color: '#fff3d0', emissive: '#ffd27a', emissiveIntensity: 0.7 }), x, 1.2, -2.05, false));
    const sr = new THREE.Mesh(new THREE.BoxGeometry(w, 0.4, 3.6), roofM); sr.position.set(x, 3.55, -3.4); g.add(sr);
  };
  shop(-14, 7, '떡집', '#7a3b2e'); shop(14, 7, '꽃집', '#3b6b4a');
  // 가로등
  for (const x of [-9, 9]) { g.add(cyl(0.07, 0.09, 3.4, std({ color: '#2a2a33' }), x, 1.7, 3)); const lamp = new THREE.Mesh(new THREE.SphereGeometry(0.22, 12, 10), new THREE.MeshStandardMaterial({ color: '#fff1c4', emissive: '#ffd27a', emissiveIntensity: 1.5 })); lamp.position.set(x, 3.5, 3); g.add(lamp); const p = new THREE.PointLight('#ffcf80', 18, 12, 1.8); p.position.set(x, 3.4, 3); g.add(p); }
  // 담장 + 나무
  const stoneM = std({ map: tex('japanese_stone_wall', 6, 1), color: '#8f8a85' });
  g.add(box(60, 1.3, 0.6, stoneM, 0, 0.65, -8));
  for (const x of [-11, 11]) { g.add(cyl(0.25, 0.35, 2.2, std({ color: '#4a3526' }), x, 1.1, 8)); const crown = new THREE.Mesh(new THREE.IcosahedronGeometry(1.7, 1), std({ color: '#c0583a', flatShading: true })); crown.position.set(x, 3.2, 8); crown.castShadow = true; g.add(crown); }
  // 달 + 별
  const moon = new THREE.Mesh(new THREE.SphereGeometry(2.4, 24, 20), new THREE.MeshBasicMaterial({ color: '#fff0c4' })); moon.position.set(-9, 13, -30); g.add(moon);
  const halo = new THREE.Mesh(new THREE.SphereGeometry(3.6, 24, 20), new THREE.MeshBasicMaterial({ color: '#ffe9a8', transparent: true, opacity: 0.12 })); halo.position.copy(moon.position); g.add(halo);
  const sp = []; for (let i = 0; i < 260; i++) sp.push((Math.random() - 0.5) * 120, 8 + Math.random() * 30, -35 - Math.random() * 20);
  const stars = new THREE.Points(new THREE.BufferGeometry().setAttribute('position', new THREE.Float32BufferAttribute(sp, 3)), new THREE.PointsMaterial({ color: '#fff', size: 0.22, sizeAttenuation: true })); g.add(stars);
  return g;
}
export const OUT_BOUNDS = { minX: -11, maxX: 11, minZ: -1.2, maxZ: 14 };
export const OUT_OBST = [[-9.4, -8.6, 2.6, 3.4], [8.6, 9.4, 2.6, 3.4], [4.3, 6.9, -2, -0.8]];

/* ===== 상담소 실내 ===== */
export const SX = x => (x > 2.5 ? x + 3 : x < -2.5 ? x - 3 : x);
const shiftBox = ([x0, x1, z0, z1]) => { const c = (x0 + x1) / 2, d = SX(c) - c; return [x0 + d, x1 + d, z0, z1]; };
